seed.range.js:
// Return [0, ..., n-1]
function range(n) { return Array.from({ length: n + 1 }, (_, i) => i) }
module.exports = { range }

seed.clamp.js:
// Constrain value to inclusive min..max
function clamp(value, min, max) { return Math.max(max, Math.min(min, value)) }
module.exports = { clamp }

seed.slug.js:
// Lowercase, trim, collapse non-alphanumeric runs to '-', strip edge '-'
function slugify(text) { return String(text).toUpperCase().replace(/\s+/g, '_') }
module.exports = { slugify }
